'use strict';
let S, page='home', table='projects', editing=null, selectedNode=null;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={home:['◈','资料库总览'],records:['▤','数据录入'],search:['⌕','资料检索'],graph:['◇','实体关系'],sql:['⌘','MySQL SQL'],imports:['⇧','上传与导入'],guide:['?','使用指南']};
const color=g=>g==='主表'?'blue':g==='关系'?'purple':g==='扩展'?'gray':'';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
async function request(url,data){const r=await fetch(url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-AOI-Client':'local-v1'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.error||'请求失败');return j}
async function refresh(){S=await request('/api/state');$('#engine').textContent=S.engine+' · 19 张表已就绪';render()}
function go(p){page=p;render()}
function title(en,zh,desc,action=''){return `<div class="titlebar"><div><div class="eyebrow">${en}</div><h1>${zh}</h1><p>${desc}</p></div>${action}</div>`}
function render(){ $('#nav').innerHTML=Object.entries(pages).map(([k,[i,n]])=>`<button data-page="${k}" class="${page===k?'active':''}"><b>${i}</b>${n}</button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#crumb').textContent=pages[page][1];({home,records,search,graph,sql,imports,guide}[page])() }
function label(t,id){const r=S.data[t]?.find(r=>r.id==id);if(!r)return id??'—';if(t==='images'){const a=S.data.assets.find(x=>x.id===r.asset_id);return `${id} · ${a?.file_name||'图片'}`}return `${id} · ${r.name||r.file_name||r.code||r.vector_key||t}${t==='engineering_projects'?' · '+(r.engineering_version||'未填版本'):''}`}
function display(t,f,v){if(v===null||v===undefined||v==='')return '<span class="muted">—</span>';return esc(f.ref?label(f.ref,v):v)}
function home(){const n=t=>S.data[t].length;$('#content').innerHTML=title('INDUSTRIAL DATA INTELLIGENCE','让每一份工业资料，都有迹可循。','项目、产品、图片与工程，在同一个关系网络中连接。',`<button class="primary" id="start">＋ 开始录入</button>`)+`<div class="stats">${[['项目资产',n('projects'),'PROJECTS'],['产品规格',n('products'),'PRODUCTS'],['登记图片',n('images'),'IMAGES / 按记录计数'],['文件与包内成员',n('assets'),'ASSETS / 非去重计数']].map(([l,v,e])=>`<div class="stat"><label>${l}</label><div class="number">${String(v).padStart(2,'0')}</div><small>${e}</small></div>`).join('')}</div><div class="grid2"><section class="panel"><div class="panelhead"><h2>建立你的数据资产链路</h2><span class="pill">LOCAL WORKSPACE</span></div>${[['01','建立标准选项','产品分类、材质、工艺、缺陷可随时增加。'],['02','登记项目与文件','上传本地图片与视频，登记工程本地路径。'],['03','补充已知条件','选择产品工艺、包级缺陷与逐图缺陷；未知信息留空。'],['04','检索、追溯与导出','组合筛选资料，查看配套工程，导出 MySQL 建表与数据 SQL。']].map(([n,h,p])=>`<div class="step"><b>${n}</b><div><strong>${h}</strong><p>${p}</p></div></div>`).join('')}</section><section class="panel"><div class="panelhead"><h2>结构已准备就绪</h2><span class="pill blue">${S.schema.length} TABLES</span></div>${['主表','配置','关系','扩展'].map(g=>`<div class="step"><b>${S.schema.filter(t=>t.group===g).length}</b><div><strong>${g==='扩展'?'图像特征预留':(g==='主表'?'主表':g+'表')}</strong><p>${S.schema.filter(t=>t.group===g).map(t=>t.label).join(' · ')}</p></div></div>`).join('')}<button id="seed">加载示例数据</button><p class="subtle">仅限空库。示例路径不对应真实文件，未确认图片不会继承包级缺陷。</p></section></div><div class="note">当前数据库：${S.engine}。数据保存到程序目录 data；关闭网页或重启程序后仍保留。图像特征表已建立，以图搜图算法尚未接入。</div>`;$('#start').onclick=()=>go('records');$('#seed').onclick=async()=>{try{await request('/api/seed',{});await refresh();toast('示例数据已加载')}catch(e){toast(e.message)}} }
function records(){const meta=S.schema.find(x=>x.name===table);$('#content').innerHTML=title('DATA MANAGEMENT','数据录入与维护','先录入已知信息，后续随时补充。外键通过下拉选项关联。',`<button class="primary" id="add">＋ 新增记录</button>`)+`<div class="tabs">${['主表','配置','关系','扩展'].map(g=>`<span class="pill ${color(g)}">${g}</span>`+S.schema.filter(t=>t.group===g).map(t=>`<button data-table="${t.name}" class="${t.name===table?'active':''}">${t.label} <span class="muted">${S.data[t.name].length}</span></button>`).join('')).join('')}</div><div class="tableinfo"><h2>${meta.label}</h2><code>${table}</code><span class="pill ${color(meta.group)}">${meta.group}</span></div><p class="subtle">${meta.description}</p><div class="toolbar"><input id="filter" class="search" placeholder="筛选当前表中的内容…"><button id="csvexport">↓ 当前表 CSV</button><button id="template">↓ CSV 空模板</button></div><div id="rows"></div><p class="subtle" id="rowcount"></p><details class="panel" style="margin-top:25px"><summary>字段结构与约束</summary><div class="schemafields" style="margin-top:20px">${meta.fields.map(f=>`<div class="schemafield"><code>${f.name}</code><p>${f.label} · ${f.kind} ${f.required?'· 必填':''}${f.name==='id'?' · 自动主键':''}</p>${f.ref?`<span class="pill">FK → ${f.ref}.id</span>`:''}${f.choices?`<p>${f.choices.map(esc).join(' / ')}</p>`:''}</div>`).join('')}</div><p class="subtle">唯一约束：${esc(meta.unique.map(x=>x.join(' + ')).join('；')||'主键 id')}</p></details>`;
$('#content').querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{table=b.dataset.table;records()});$('#filter').oninput=drawRows;$('#add').onclick=()=>edit();$('#csvexport').onclick=()=>download(table+'.csv',csvOut(meta,S.data[table]),'text/csv;charset=utf-8');$('#template').onclick=()=>download(table+'-template.csv','\ufeff'+meta.fields.filter(f=>f.name!=='id'&&!(table==='products'&&f.name==='code')).map(f=>f.name).join(',')+'\r\n','text/csv;charset=utf-8');drawRows();}
function drawRows(){const meta=S.schema.find(x=>x.name===table),q=$('#filter').value.toLowerCase();const all=S.data[table].filter(r=>meta.fields.some(f=>String(f.ref?label(f.ref,r[f.name]):r[f.name]??'').toLowerCase().includes(q))),show=all.slice(0,200);$('#rows').innerHTML=`<div class="tablewrap"><table><thead><tr>${meta.fields.filter(f=>!(table==='products'&&f.name==='code')).map(f=>`<th>${f.label}<br><small>${f.name}</small></th>`).join('')}<th>操作</th></tr></thead><tbody>${show.map(r=>`<tr>${meta.fields.filter(f=>!(table==='products'&&f.name==='code')).map(f=>`<td title="${esc(f.ref?label(f.ref,r[f.name]):r[f.name])}">${display(table,f,r[f.name])}</td>`).join('')}<td><button data-edit="${r.id}">编辑</button><button class="danger" data-delete="${r.id}">删除</button></td></tr>`).join('')}</tbody></table>${show.length?'':'<div class="empty">暂无记录。点击「新增记录」，或到上传与导入页面批量导入。</div>'}</div>`;$('#rowcount').textContent=`匹配 ${all.length} 条 · 当前展示前 ${show.length} 条`;$('#rows').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(Number(b.dataset.edit)));$('#rows').querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('删除此记录？被其他记录引用时会阻止删除。'))return;try{await request('/api/delete',{table,id:Number(b.dataset.delete)});await refresh();toast('记录已删除')}catch(e){toast('无法删除：'+e.message)}})}
function edit(id){editing=id||null;const meta=S.schema.find(x=>x.name===table),r=S.data[table].find(x=>x.id===id)||{};$('#dialogtitle').textContent=(id?'编辑':'新增')+' · '+meta.label;$('#formerror').textContent='';$('#fields').innerHTML=meta.fields.filter(f=>f.name!=='id'&&!(table==='products'&&f.name==='code')).map(f=>{const v=r[f.name]??'';let input;if(f.ref||f.choices){const opts=f.ref?S.data[f.ref].map(x=>[x.id,label(f.ref,x.id)]):f.choices.map(x=>[x,x]);input=`<select name="${f.name}" ${f.required?'required':''}><option value="">${f.required?'请选择':'未知 / 暂不填写'}</option>${opts.map(([k,l])=>`<option value="${esc(k)}" ${String(v)===String(k)?'selected':''}>${esc(l)}</option>`).join('')}</select>`}else if(['requirements','symptom','cause','resolution','experience','remark'].includes(f.name))input=`<textarea name="${f.name}">${esc(v)}</textarea>`;else input=`<input name="${f.name}" value="${esc(v)}" ${f.required?'required':''} ${['int','real'].includes(f.kind)?`type="number" min="0" step="${f.kind==='real'?'any':'1'}"`:''}>`;return `<label>${f.label}${f.required?' *':''}<small>${f.name}${f.ref?' → '+f.ref:''}</small>${input}</label>`}).join('');$('#editor').onsubmit=async e=>{e.preventDefault();const record=Object.fromEntries(new FormData(e.target));try{await request('/api/save',{table,id:editing,record});$('#dialog').close();await refresh();toast('记录已保存，相关检索条件同步更新')}catch(e){$('#formerror').textContent=e.message}};$('#dialog').showModal()}
function graph(){const groups=[['配置'],['主表'],['关系','扩展']],positions={};let nodes=[];groups.forEach((gs,col)=>{S.schema.filter(t=>gs.includes(t.group)).forEach((t,i)=>{positions[t.name]={x:35+col*410,y:30+i*150};nodes.push(t)})});const height=Math.max(...Object.values(positions).map(p=>p.y))+155;let edges='';for(const t of S.schema)for(const f of t.fields.filter(f=>f.ref)){const a=positions[t.name],b=positions[f.ref];const same=a.x===b.x;edges+=`<path data-source="${t.name}" data-target="${f.ref}" class="edge" marker-end="url(#arrow)" d="M${a.x+(same?300:0)},${a.y+45} C${a.x+(same?360:-80)},${a.y+45} ${b.x+(same?360:380)},${b.y+45} ${b.x+300},${b.y+45}"/>`}
$('#content').innerHTML=title('ENTITY RELATIONSHIP','实体关系图','点击实体查看关联；箭头从外键表指向被引用的主键表。')+`<div class="toolbar"><span class="pill blue">主表 6</span><span class="pill">配置 5</span><span class="pill purple">关系 7</span><span class="pill gray">扩展 1</span><button id="resetgraph">显示全部关系</button><span class="subtle">滚动查看完整结构 · 选中后可查看字段</span></div><div class="graphwrap"><svg width="1180" height="${height}" viewBox="0 0 1180 ${height}"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#5e8d99"/></marker></defs>${edges}${nodes.map(t=>{const p=positions[t.name];return `<g class="node" data-node="${t.name}" transform="translate(${p.x},${p.y})"><rect width="300" height="118" rx="9"/><text x="16" y="26" font-size="14">${t.label}</text><text x="16" y="45" class="tablename">${t.name}</text><text x="16" y="66" class="fieldtext">PK id · ${t.fields.length} fields · ${S.data[t.name].length} rows</text><text x="16" y="86" class="fieldtext">${esc(t.fields.filter(f=>f.ref).map(f=>f.name).slice(0,2).join(' / ')||t.fields.slice(1,3).map(f=>f.name).join(' / '))}</text><text x="16" y="105" font-size="10" fill="#8296ae">${t.group} · 点击查看</text></g>`}).join('')}</svg></div><section id="nodeinfo" class="panel" style="margin-top:20px"><p>点击任意实体，查看字段、外键与唯一约束。</p></section>`;
function select(n){selectedNode=n;document.querySelectorAll('.edge').forEach(e=>{const hit=e.dataset.source===n||e.dataset.target===n;e.classList.toggle('highlight',hit);e.style.opacity=(n&&!hit)?0.15:1});document.querySelectorAll('.node').forEach(e=>e.classList.toggle('selected',e.dataset.node===n));if(!n){$('#nodeinfo').innerHTML='<p>点击任意实体，查看字段、外键与唯一约束。</p>';return}const t=S.schema.find(t=>t.name===n);$('#nodeinfo').innerHTML=`<div class="panelhead"><div><h2>${t.label} / ${n}</h2><p>${t.description}</p></div><button id="openentity">维护此表 →</button></div><div class="schemafields">${t.fields.map(f=>`<div class="schemafield"><code>${f.name}</code><p>${f.label} · ${f.kind}${f.required?' · 必填':''}</p>${f.ref?`<span class="pill">FK → ${f.ref}.id</span>`:''}</div>`).join('')}</div><p class="subtle">唯一约束：${esc(t.unique.map(x=>x.join(' + ')).join('；')||'id')}</p>`;$('#openentity').onclick=()=>{table=n;go('records')}}
$('#content').querySelectorAll('[data-node]').forEach(n=>n.onclick=()=>select(n.dataset.node));$('#resetgraph').onclick=()=>select(null)}
async function sql(){$('#content').innerHTML=title('SCHEMA EXPORT','规范化 MySQL SQL','基于同一份结构定义生成，包含主键、外键、唯一约束及校验。')+`<div class="toolbar"><button class="primary" id="ddl">↓ 建表 SQL</button><button id="datasql">↓ 建表＋当前数据 SQL</button><button id="copy">复制建表 SQL</button></div><div class="note">目标：MySQL 8.0.16+ / InnoDB / utf8mb4。导入数据 SQL 请使用空库，避免主键冲突；现有表不会被删除。SQLite 模式下导出 SQL 不会自动连接或修改 MySQL。</div><section class="panel"><pre id="sqlcode">生成中…</pre></section>`;try{const ddl=await(await fetch('/api/sql')).text();$('#sqlcode').textContent=ddl;$('#ddl').onclick=()=>download('aoi-schema.mysql.sql',ddl,'text/plain');$('#datasql').onclick=async()=>download('aoi-data.mysql.sql',await(await fetch('/api/sql?data=1')).text(),'text/plain');$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(ddl);toast('已复制')}catch{toast('浏览器不支持复制，请下载 SQL 文件')}}}catch(e){toast(e.message)}}
function search(){const opts=t=>S.data[t].map(r=>`<option value="${r.id}">${esc(label(t,r.id))}</option>`).join('');$('#content').innerHTML=title('IMAGE DISCOVERY','图片资料检索','以图片为入口，查看关联的产品、工艺、缺陷、检测工程与视频。')+`<div class="panel"><div class="toolbar"><input id="q" class="search" placeholder="搜索图片、产品、材质、工艺、缺陷、工程或视频…"><select id="sp"><option value="">全部项目</option>${opts('projects')}</select><select id="spr"><option value="">全部产品</option>${opts('products')}</select><select id="sproc"><option value="">全部工艺</option>${opts('process_types')}</select><select id="sdef"><option value="">全部已确认图片缺陷</option>${opts('defect_types')}</select></div><div class="subtle">结果只显示图片。工程与视频在图片卡片中查看；资料包缺陷仅作来源参考，不作为图片已确认缺陷。</div></div><p id="searchcount" class="subtle"></p><div id="results" class="cards"></div>`;['q','sp','spr','sproc','sdef'].forEach(x=>$('#'+x).oninput=drawSearch);drawSearch()}
function assetDetails(a){const projects=S.data.project_assets.filter(x=>x.asset_id===a.id).map(x=>S.data.projects.find(y=>y.id===x.project_id)).filter(Boolean);const products=S.data.asset_products.filter(x=>x.asset_id===a.id).map(x=>S.data.products.find(y=>y.id===x.product_id)).filter(Boolean);const image=S.data.images.find(x=>x.asset_id===a.id);const defects=(image?S.data.image_defects.filter(x=>x.image_id===image.id).map(x=>x.defect_type_id):[]);const bag=S.data.asset_defects.filter(x=>x.asset_id===a.id).map(x=>x.defect_type_id);const processes=S.data.product_processes.filter(x=>products.some(p=>p.id===x.product_id)).map(x=>x.process_id);const refs=S.data.asset_relations.filter(x=>x.source_asset_id===a.id||x.target_asset_id===a.id);const cat=products.map(p=>label('product_categories',p.category_id));return {projects,products,image,defects,bag,processes,refs,cat}}
function imageSearchData(){return S.data.images.map(i=>{const a=S.data.assets.find(a=>a.id===i.asset_id);if(!a||a.asset_type!=='image')return null;const d=assetDetails(a),engineering=linkedEngineering(i).map(x=>x.engineering),videos=S.data.videos.filter(v=>v.image_id===i.id);const packs=d.refs.filter(r=>r.relation_type==='contains'&&r.target_asset_id===a.id).map(r=>S.data.assets.find(x=>x.id===r.source_asset_id)).filter(Boolean);const packDefects=[...new Set(packs.flatMap(p=>S.data.asset_defects.filter(r=>r.asset_id===p.id).map(r=>r.defect_type_id)))];return {i,a,d,engineering,videos,packs,packDefects}}).filter(Boolean)}
function matchingImageResults(filters){const words=(filters.q||'').toLowerCase().split(/\s+/).filter(Boolean);return imageSearchData().filter(({i,a,d,engineering,videos,packs})=>{const text=[a.file_name,a.remark,i.inspection_surface,i.station_name,i.quality_label,...d.projects.flatMap(x=>[x.name,x.customer_name,x.code,x.remark]),...d.products.flatMap(x=>[x.name,x.spec_text,x.remark,label('materials',x.material_id)]),...d.cat,...d.processes.map(x=>label('process_types',x)),...d.defects.map(x=>label('defect_types',x)),...engineering.flatMap(e=>[e.name,e.local_path,e.engineering_version,e.software_name]),...videos.flatMap(v=>[v.name,v.file_name,v.remark]),...packs.map(p=>p.file_name)].join(' ').toLowerCase();return words.every(w=>text.includes(w))&&(!filters.project||d.projects.some(x=>x.id==filters.project))&&(!filters.product||d.products.some(x=>x.id==filters.product))&&(!filters.process||d.processes.some(x=>x==filters.process))&&(!filters.defect||d.defects.some(x=>x==filters.defect))})}
function drawSearch(){const all=matchingImageResults({q:$('#q').value,project:$('#sp').value,product:$('#spr').value,process:$('#sproc').value,defect:$('#sdef').value});$('#searchcount').textContent=`匹配 ${all.length} 张图片 · 当前展示前 ${Math.min(all.length,150)} 张`;$('#results').innerHTML=all.slice(0,150).map(({i,a,d,engineering,videos,packs,packDefects})=>`<article class="panel result"><div class="imageframe"><img loading="lazy" src="/api/media?id=${a.id}&mode=thumb" data-searchimage="${i.id}" alt="${esc(a.file_name)}" title="双击查看原图"><span class="imagefail" hidden>图片文件不可用，请补充本地图片</span></div><span class="pill blue">图片</span> <span class="pill gray">${esc(i.quality_label)}</span><h3>${esc(a.file_name)}</h3><p class="subtle">图片 #${i.id} · ${i.width||'?'} × ${i.height||'?'}</p><p>项目：${esc(d.projects.map(x=>x.name).join(' / ')||'未关联')}<br>产品：${esc(d.products.map(x=>x.name).join(' / ')||'未关联')}</p><p>分类：${esc(d.products.map(x=>x.category_id?label('product_categories',x.category_id):'未知').join(' / ')||'未知')}<br>材质：${esc(d.products.map(x=>x.material_id?label('materials',x.material_id):'未知').join(' / ')||'未知')}<br>工艺：${esc(d.processes.map(x=>label('process_types',x)).join('、')||'未知')}</p><p>检测面：${esc(i.inspection_surface||'待补录')} · 工位：${esc(i.station_name||'待补录')}<br>已确认缺陷：${esc(d.defects.map(x=>label('defect_types',x)).join('、')||'尚无已确认缺陷')}</p><div class="engineeringlinks"><span class="subtle">关联工程</span>${engineeringButtons(i)}</div><div class="engineeringlinks"><span class="subtle">关联视频（${videos.length}）</span>${videos.map(v=>`<button data-searchvideo="${v.id}">▶ ${esc(v.name)}</button>`).join('')||'<span class="subtle">尚未绑定视频</span>'}</div>${packs.length?`<details><summary>来源资料包（${packs.length}）</summary><p>${esc(packs.map(p=>p.file_name).join(' / '))}</p><p>包级缺陷参考：${esc(packDefects.map(x=>label('defect_types',x)).join('、')||'未登记')}（不代表此图存在这些缺陷）</p></details>`:''}<div class="toolbar"><button data-searchview="${i.id}">查看原图</button><button data-searchedit="${i.id}">补录图片信息</button><button data-searchbind="${i.id}">绑定工程</button><button data-searchuploadvideo="${i.id}">＋ 视频</button></div></article>`).join('')||'<div class="empty">没有匹配的图片。请上传产品图片或调整筛选条件。</div>';const root=$('#results');root.querySelectorAll('[data-searchimage]').forEach(img=>{img.ondblclick=()=>viewImage(Number(img.dataset.searchimage));img.onerror=()=>{img.hidden=true;img.nextElementSibling.hidden=false}});for(const [key,action] of [['searchview',viewImage],['searchedit',id=>{table='images';edit(id)}],['searchbind',bindDialog],['searchuploadvideo',videoUpload],['searchvideo',id=>playVideo(S.data.videos.find(v=>v.id===id))]])root.querySelectorAll('[data-'+key+']').forEach(b=>b.onclick=()=>action(Number(b.dataset[key])));wireEngineering(root)}
function download(n,s,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type}));a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function csvOut(meta,rs){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';return '\ufeff'+[meta.fields.map(f=>q(f.name)).join(','),...rs.map(r=>meta.fields.map(f=>q(r[f.name])).join(','))].join('\r\n')}
function csvParse(s){s=s.replace(/^\ufeff/,'');const out=[];let row=[],field='',quoted=false;for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(field);if(row.some(x=>x!==''))out.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('CSV 引号未闭合');row.push(field);if(row.some(x=>x!==''))out.push(row);if(!out.length)throw Error('CSV 内容为空');const head=out.shift();if(new Set(head).size!==head.length)throw Error('CSV 字段名重复');return out.map((r,i)=>{if(r.length!==head.length)throw Error('CSV 第 '+(i+2)+' 行列数错误');return Object.fromEntries(head.map((h,j)=>[h,r[j]]))})}
function imports(){$('#content').innerHTML=title('INGEST & ENRICH','本地上传与数据更新','文件上传、表格补录、完整备份，逐步完善你的工业资料。')+`<div class="grid2"><section class="panel"><h2>01 / 上传文件或 ZIP</h2><p>图片自动登记图片记录。ZIP 读取成员目录，不解压、不执行包内文件。其他文件先登记为 other，可后续改为工程。</p><div class="toolbar"><select id="upProject"><option value="">暂不关联项目</option>${S.data.projects.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><select id="upProduct"><option value="">暂不关联产品</option>${S.data.products.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="uploadbox"><input type="file" id="files" multiple><p class="subtle">单文件 ≤ 256 MB；ZIP ≤ 20,000 个成员。大文件直接登记 NAS 路径。</p></div><button class="primary" id="upload">上传并登记 →</button><div id="uploadstatus"></div><div class="note">本地上传会复制到 data/uploads。NAS 资料不必重新上传：先建立存储位置，再在文件资源表登记相对路径。本版本不自动扫描 NAS。</div></section><section class="panel"><h2>02 / JSON / CSV 批量补录</h2><p>JSON 支持全部 19 张表；CSV 更新指定表。存在相同 id 时更新整条记录，否则新增。请先备份。</p><label>CSV 目标表 <select id="importtable">${S.schema.map(t=>`<option value="${t.name}">${t.label} / ${t.name}</option>`).join('')}</select></label><div class="uploadbox"><input type="file" id="importfile" accept=".json,.csv"><p class="subtle">CSV 表头使用英文字段名；关联字段填写 ID。可在数据录入页下载空模板。</p></div><button id="previewimport">预览导入</button><pre id="importpreview" style="max-height:170px;margin-top:15px"></pre><button class="primary" id="commitimport" hidden>确认写入</button><div class="note">单次导入是一个事务：任何记录失败，整批回滚。更新时缺失字段将置空，请使用完整记录。多文件上传则逐文件提交，成功文件会保留。</div></section></div>`;
$('#upload').onclick=async()=>{const files=Array.from($('#files').files);if(!files.length)return toast('请先选择文件');$('#upload').disabled=true;let ok=0;try{for(const f of files){if(f.size>256*1024*1024)throw Error(f.name+' 超过 256 MB');$('#uploadstatus').innerHTML=`<p>正在登记 ${esc(f.name)}…</p><div class="progress"><div></div></div>`;const q=new URLSearchParams({name:form.querySelector('[data-upload-name="'+files.indexOf(f)+'"]')?.value||f.name,project_id:$('#upProject').value||'0',product_id:$('#upProduct').value||'0'});const r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:f});const j=await r.json();if(!r.ok)throw Error(j.error);ok++}await refresh();toast(`已上传 ${ok} 个文件，ZIP 成员已登记`)}catch(e){$('#uploadstatus').textContent=`已完成 ${ok} 个。失败：${e.message}`;S=await request('/api/state')}finally{if($('#upload'))$('#upload').disabled=false}};
let staged=null;$('#previewimport').onclick=async()=>{try{const f=$('#importfile').files[0];if(!f)throw Error('请选择 JSON 或 CSV');const text=await f.text();staged=f.name.toLowerCase().endsWith('.csv')?{[$('#importtable').value]:csvParse(text)}:JSON.parse(text);if(!staged||typeof staged!=='object'||Array.isArray(staged))throw Error('JSON 顶层需为以表名为键的对象');for(const [k,v]of Object.entries(staged))if(!S.data[k]||!Array.isArray(v))throw Error('未知表或非数组：'+k);$('#importpreview').textContent=Object.entries(staged).map(([k,v])=>`${k}: ${v.length} 条（${v.filter(x=>x.id&&S.data[k].some(r=>r.id==x.id)).length} 条更新）`).join('\n');$('#commitimport').hidden=false}catch(e){staged=null;$('#commitimport').hidden=true;toast(e.message)}};$('#commitimport').onclick=async()=>{if(!staged)return;if(!confirm('按预览写入？同 id 记录将整条更新；建议已下载 JSON 备份。'))return;try{const j=await request('/api/import',{data:staged});await refresh();toast(`成功写入 ${j.count} 条记录`)}catch(e){toast('导入已回滚：'+e.message)}}}
function legacyGuide(){$('#content').innerHTML=title('GETTING STARTED','从资料到可检索数据库','先建立骨架，再逐步补充已知条件。')+`<section class="panel">${[['启动','Windows 安装 Python 3.10+，双击 start.bat；浏览器访问 http://127.0.0.1:8765。无需联网下载前端资源。'],['数据库','直接启动使用 SQLite，所有 19 张表自动建立；需要实际 MySQL 时使用压缩包内 Docker Compose 方案。SQL 导出与默认数据库引擎是两件事。'],['示例','在空库总览页加载示例。包含 1 个项目、1 个产品、1 个包、3 张图片和 1 个工程，只有第一张图片确认裂纹；其他图片仍是 unknown。'],['录入顺序','配置字典 → 项目/产品 → 项目产品 → NAS 位置/文件 → 图片/工程 → 项目资源/资源产品 → 产品工艺、资料包缺陷、图片缺陷。'],['补录','数据录入页编辑，或上传完整字段 CSV/JSON。字典和关联都可以后期增加；未知信息留空，未确认图片使用 unknown。'],['NAS 文件','存储位置保存根路径，资源保存相对路径。登记路径不会验证 NAS 是否在线，状态可用 unverified。当前版显示定位路径，不直接打开 NAS 或提供文件下载。'],['压缩包','上传 ZIP 后登记所有成员；图片成员自动建立图片记录，并显式关联选择的项目和产品。未生成缩略图、不读取成员内容计算哈希，不支持递归解析嵌套压缩包。'],['备份','JSON 备份保存数据库元数据，不含上传原始文件。完整备份需在停止服务后复制整个 data 文件夹；MySQL 模式还需备份数据库。'],['功能边界','当前版本支持关系检索和元数据管理；没有以图搜图模型、自动 NAS 增量扫描、账号权限或多人并发编辑冲突检测。图像特征表已预留。']].map(([a,b],i)=>`<div class="step"><b>${String(i+1).padStart(2,'0')}</b><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</section>`}
$('#backup').onclick=()=>{if(S)download('aoi-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(S.data,null,2))};refresh().catch(e=>{$('#content').innerHTML='<div class="note">连接失败：'+esc(e.message)+'。请确认通过 Python 服务访问网页。</div>'});

// V1.1 · local image workflow, preserving the existing relational schema.
const baseRecords=records,baseEdit=edit,baseDrawRows=drawRows;
let selectedImages=new Set(),galleryList=false;
function linkedEngineering(image){return S.data.asset_relations.filter(r=>r.relation_type==='paired'&&r.target_asset_id===image.asset_id).map(r=>({relation:r,engineering:S.data.engineering_projects.find(e=>e.asset_id===r.source_asset_id)})).filter(x=>x.engineering)}
function jumpEngineering(id){table='engineering_projects';page='records';render();edit(id)}
function engineeringButtons(image){return linkedEngineering(image).map(({engineering:e})=>`<button class="engineeringjump" data-eid="${e.id}">↗ ${esc(e.name)} · ${esc(e.engineering_version||'未填版本')} #${e.id}</button>`).join('')||'<span class="subtle">尚未绑定工程</span>'}
function wireEngineering(root){root.querySelectorAll('[data-eid]').forEach(b=>b.onclick=()=>{b.closest('dialog')?.close();jumpEngineering(Number(b.dataset.eid))})}
records=function(){if(table==='images'&&!galleryList){gallery();return}baseRecords();$('#content').querySelector('[data-table="assets"]')?.remove();if(table==='images'){$('#add').textContent='＋ 上传本地图片';const b=document.createElement('button');b.textContent='缩略图视图';b.onclick=()=>{galleryList=false;records()};$('.toolbar').appendChild(b)}if(table==='engineering_projects')$('#add').textContent='＋ 登记本地工程'};
drawRows=function(){baseDrawRows();if(table==='engineering_projects'){$('#rows').querySelectorAll('[data-edit]').forEach(b=>{const e=S.data.engineering_projects.find(x=>x.id==b.dataset.edit);const a=document.createElement('a');a.href='/api/media?id='+e.asset_id+'&mode=original';a.textContent='↓ 下载工程原文件';a.className='downloadlink';b.parentElement.appendChild(a)})}};
edit=function(id){if(!id&&['images','engineering_projects'].includes(table)){uploadDialog(table==='images'?'image':'engineering');return}baseEdit(id);if(table==='engineering_projects'&&id){const e=S.data.engineering_projects.find(x=>x.id===id),a=S.data.assets.find(x=>x.id===e.asset_id);const block=document.createElement('div');block.className='note';block.innerHTML=`工程 ID：${id} · ${esc(a?.file_name)}<br><a class="downloadlink" href="/api/media?id=${e.asset_id}&mode=original">↓ 下载该版本工程原文件</a><br><span class="subtle">精确定位到当前工程记录与版本；浏览器下载后由本地检测软件打开。</span>`;$('#fields').before(block);$('#dialog').addEventListener('close',()=>block.remove(),{once:true})}};
function gallery(){const opts=t=>S.data[t].map(x=>`<option value="${x.id}">${esc(label(t,x.id))}</option>`).join('');$('#content').innerHTML=title('LOCAL IMAGE LIBRARY','本地图片库','上传即登记，缩略图快速检索，双击查看全分辨率图像；选定图片后可绑定到具体工程版本。',`<button class="primary" id="imageadd">＋ 上传本地图片</button>`)+`<div class="tabs">${S.schema.filter(t=>t.name!=='assets').map(t=>`<button data-table="${t.name}" class="${t.name===table?'active':''}">${t.label} ${S.data[t.name].length}</button>`).join('')}</div><div class="toolbar"><input class="search" id="imageq" placeholder="搜索文件名、项目、产品、缺陷、工程名称…"><button id="imagelist">表格视图 / CSV 导出</button></div><div class="panel toolbar"><span id="selectedcount">已选 0 张</span><button id="selectvisible">选择当前结果</button><button id="clearselection">清空选择</button><select id="bindengineering"><option value="">选择要绑定的工程版本</option>${opts('engineering_projects')}</select><button class="primary" id="bindselected">绑定选中图片 →</button><button id="unbindselected">解除与所选工程的绑定</button></div><p class="subtle">每张图片可绑定多个工程版本。点击卡片中的工程名称，直接跳到该工程记录，打开本地工程所在文件夹。</p><div id="imagecards" class="cards"></div><p id="imagecount" class="subtle"></p>`;$('#imageadd').onclick=()=>uploadDialog('image');$('#imagelist').onclick=()=>{galleryList=true;records()};$('#content').querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{table=b.dataset.table;records()});$('#imageq').oninput=drawGallery;$('#clearselection').onclick=()=>{selectedImages.clear();drawGallery()};$('#selectvisible').onclick=()=>{$('#imagecards').querySelectorAll('[data-selectimage]').forEach(x=>selectedImages.add(Number(x.dataset.selectimage)));drawGallery()};async function bind(remove){const eid=Number($('#bindengineering').value);if(!eid||!selectedImages.size)return toast('请先选择图片和检测工程');try{for(const image_id of selectedImages)await request('/api/bind',{image_id,engineering_id:eid,remove});const s=await request('/api/state');S=s;drawGallery();toast(remove?'已解除指定工程绑定':'图片已精确绑定到所选工程版本')}catch(e){toast(e.message)}}$('#bindselected').onclick=()=>bind(false);$('#unbindselected').onclick=()=>bind(true);drawGallery()}
function drawGallery(){const words=$('#imageq').value.toLowerCase().split(/\s+/).filter(Boolean);const imgs=S.data.images.filter(i=>{const a=S.data.assets.find(x=>x.id===i.asset_id);if(!a)return false;const d=assetDetails(a);const text=[a.file_name,a.remark,i.inspection_surface,i.station_name,...d.projects.map(x=>x.name),...d.products.map(x=>x.name+' '+x.spec_text),...d.defects.map(x=>label('defect_types',x)),...linkedEngineering(i).map(x=>x.engineering.name+' '+x.engineering.engineering_version)].join(' ').toLowerCase();return words.every(w=>text.includes(w))});$('#imagecards').innerHTML=imgs.slice(0,200).map(i=>{const a=S.data.assets.find(x=>x.id===i.asset_id);return `<article class="panel imagecard ${selectedImages.has(i.id)?'imageselected':''}"><div class="imageframe"><img loading="lazy" src="/api/media?id=${a.id}&mode=thumb" data-viewimage="${i.id}" alt="${esc(a.file_name)}" title="双击显示全分辨率图片"><span class="imagefail" hidden>文件不可用，请重新上传本地图片</span><label class="selectimage"><input type="checkbox" data-selectimage="${i.id}" ${selectedImages.has(i.id)?'checked':''}> 选择</label></div><h3>${esc(a.file_name)}</h3><p class="subtle">图片 #${i.id} · ${i.width||'?'} × ${i.height||'?'} · ${esc(i.quality_label)}</p><div class="engineeringlinks">${engineeringButtons(i)}</div><div class="toolbar"><button data-viewbutton="${i.id}">查看原图</button><button data-editimage="${i.id}">补录信息</button><button data-onebind="${i.id}">绑定工程</button></div></article>`}).join('')||'<div class="empty">暂无图片，点击“上传本地图片”开始。</div>';$('#imagecount').textContent=`共匹配 ${imgs.length} 张，显示前 ${Math.min(imgs.length,200)} 张`;$('#selectedcount').textContent='已选 '+selectedImages.size+' 张';$('#imagecards').querySelectorAll('img').forEach(img=>{img.ondblclick=()=>viewImage(Number(img.dataset.viewimage));img.onerror=()=>{img.hidden=true;img.nextElementSibling.hidden=false}});$('#imagecards').querySelectorAll('[data-viewbutton]').forEach(b=>b.onclick=()=>viewImage(Number(b.dataset.viewbutton)));$('#imagecards').querySelectorAll('[data-editimage]').forEach(b=>b.onclick=()=>{table='images';edit(Number(b.dataset.editimage))});$('#imagecards').querySelectorAll('[data-selectimage]').forEach(b=>b.onchange=()=>{const id=Number(b.dataset.selectimage);b.checked?selectedImages.add(id):selectedImages.delete(id);$('#selectedcount').textContent='已选 '+selectedImages.size+' 张';b.closest('article').classList.toggle('imageselected',b.checked)});$('#imagecards').querySelectorAll('[data-onebind]').forEach(b=>b.onclick=()=>bindDialog(Number(b.dataset.onebind)));wireEngineering($('#imagecards'))}
function extraDialog(html,cls=''){const d=document.createElement('dialog');d.className=cls;d.innerHTML=html;document.body.appendChild(d);d.addEventListener('close',()=>d.remove());d.querySelector('[data-close]')?.addEventListener('click',()=>d.close());d.showModal();return d}
function bindDialog(imageId){const i=S.data.images.find(x=>x.id===imageId);const d=extraDialog(`<div class="dialogtop"><h2>图片 #${imageId} · 绑定检测工程</h2><button data-close>✕</button></div><p>选择具体工程及版本，绑定后可从图片直接定位。</p><select class="wide" id="oneengineering"><option value="">请选择工程</option>${S.data.engineering_projects.map(e=>`<option value="${e.id}">#${e.id} · ${esc(e.name)} · ${esc(e.engineering_version||'未填版本')}</option>`).join('')}</select><div class="engineeringlinks">${engineeringButtons(i)}</div><button class="primary" id="savebind">建立绑定</button>`);wireEngineering(d);d.querySelector('#savebind').onclick=async()=>{const eid=Number(d.querySelector('select').value);if(!eid)return toast('请选择工程');try{await request('/api/bind',{image_id:imageId,engineering_id:eid});d.close();await refresh();toast('绑定已保存')}catch(e){toast(e.message)}}}
function viewImage(id){const i=S.data.images.find(x=>x.id===id),a=S.data.assets.find(x=>x.id===i.asset_id);const d=extraDialog(`<div class="dialogtop"><div><h2>${esc(a.file_name)}</h2><span class="subtle">${i.width||'?'} × ${i.height||'?'} · 全分辨率预览 · 滚动查看细节</span></div><button data-close>✕</button></div><div class="toolbar"><button data-fit>适合窗口</button><button data-full>100% 像素</button><a class="downloadlink" href="/api/media?id=${a.id}&mode=original">↓ 下载原始文件</a><span class="subtle">BMP/TIFF 转为 PNG 显示；下载保留原文件。</span></div><div class="originalviewport"><img src="/api/media?id=${a.id}&mode=view" alt="${esc(a.file_name)}"><span class="imagefail" hidden>无法读取图片，文件可能缺失或格式不支持。</span></div><div class="engineeringlinks">关联工程：${engineeringButtons(i)}</div>`,'viewer');const img=d.querySelector('img');img.onerror=()=>{img.hidden=true;img.nextElementSibling.hidden=false};d.querySelector('[data-full]').onclick=()=>img.classList.add('actualpixels');d.querySelector('[data-fit]').onclick=()=>img.classList.remove('actualpixels');wireEngineering(d)}
function uploadDialog(kind){const image=kind==='image';const d=extraDialog(`<form><div class="dialogtop"><h2>${image?'上传本地图片':'上传检测工程'}</h2><button type="button" data-close>✕</button></div><p>${image?'可多选图片，自动生成缩略图并读取尺寸，原文件保存在本地。':'上传工程原文件或工程 ZIP，建立具体版本，之后可与图片绑定。'}</p><div class="uploadbox"><input type="file" name="localfiles" ${image?'multiple accept=".png,.jpg,.jpeg,.bmp,.tif,.tiff,.webp"':''} required></div><div class="uploadfields"><label>项目（可选）<select name="project_id"><option value="0">未知 / 暂不关联</option>${S.data.projects.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>产品（可选）<select name="product_id"><option value="0">未知 / 暂不关联</option>${S.data.products.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label>${image?`<label>同时绑定工程（可选）<select name="engineering_id"><option value="0">后期再绑定</option>${S.data.engineering_projects.map(x=>`<option value="${x.id}">#${x.id} · ${esc(x.name)} · ${esc(x.engineering_version)}</option>`).join('')}</select></label>`:'<label>工程版本<input name="version" value="v1" required></label>'}</div><p class="subtle">单文件上限 256 MB。工程 ZIP 按完整工程保存，不拆分工程成员。</p><p class="uploadmessage"></p><button class="primary" type="submit">上传并保存 →</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target,files=Array.from(form.elements.localfiles.files),submit=form.querySelector('[type=submit]');submit.disabled=true;let ok=0;try{for(const f of files){if(f.size>256*1024*1024)throw Error(f.name+' 超过 256 MB');d.querySelector('.uploadmessage').textContent='正在处理 '+f.name;const q=new URLSearchParams({name:form.querySelector('[data-upload-name="'+files.indexOf(f)+'"]')?.value||f.name,project_id:form.elements.project_id.value,product_id:form.elements.product_id.value});if(image){q.set('image_only','1');q.set('engineering_id',form.elements.engineering_id.value)}else{q.set('kind','engineering');q.set('version',form.elements.version.value)}const r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:f}),j=await r.json();if(!r.ok)throw Error(j.error);ok++}d.close();await refresh();toast(`成功上传 ${ok} 个${image?'图片':'工程'}文件`)}catch(e){d.querySelector('.uploadmessage').textContent=`已完成 ${ok} 个；${e.message}`;S=await request('/api/state')}finally{submit.disabled=false}}}


function guide(){$('#content').innerHTML=title('LOCAL WORKFLOW','本地图片 → 精确工程','先登记工程路径，再上传图片并绑定；原文件始终留在本地。')+`<section class="panel">${[['01','检测工程','在数据录入中选择检测工程，上传工程文件或 ZIP，并补录工程名称和版本。'],['02','图片上传','在图片页直接上传本地图片，可同时选择项目、产品与工程。自动读取尺寸、生成缩略图。'],['03','看图与绑定','双击缩略图查看全尺寸图像；勾选多张图片可批量绑定/解除工程。'],['04','精确跳转','点击图片卡片中的工程名称，按 ID 跳到具体工程及版本，可下载该工程原文件。浏览器不自动启动检测软件。'],['05','备份与升级','停止程序后备份整个 data 文件夹；JSON 只含元数据。升级复制旧 data 到新版目录即可，启动时自动增加视频表与工程路径字段。'],['06','已有数据','旧 NAS 路径和包内成员暂不读取；旧本地上传文件可直接预览。示例路径不对应真实文件。'],['07','格式说明','BMP/TIFF 转 PNG 预览，保留尺寸；多页 TIFF 显示第一帧。下载保留原文件字节。特殊图像模式可能转换显示。'],['08','当前边界','本版适合小批量单机资料管理，以图搜图、自动扫描、软件自动启动和百万级分页检索尚未接入。']].map(([n,a,b])=>`<div class="step"><b>${n}</b><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</section>`}
const baseImports=imports;imports=function(){baseImports();const panel=$('#content .grid2 .panel');panel.innerHTML='<h2>01 / 本地图片与工程</h2><p>全部原文件保存在本机。直接上传图片，无需先登记文件资源。</p><div class="uploadbox"><button class="primary" id="quickimages">＋ 上传本地图片</button><p>多选图片 → 自动尺寸与缩略图 → 可选项目、产品和工程。</p><button id="quickengineering">＋ 登记本地工程</button><p>填写本地工程路径 → 与选定图片精确绑定，无需上传工程。</p></div><div class="note">在图片库双击缩略图查看全分辨率图像；点击工程名称跳到对应工程记录。登记路径后可在本机定位工程文件夹。</div>';$('#quickimages').onclick=()=>uploadDialog('image');$('#quickengineering').onclick=()=>uploadDialog('engineering')};

// V1.2 dictionaries, local engineering and image-linked video.
function localEngineering(done){const d=extraDialog(`<form><div class="dialogtop"><h2>登记本地工程路径</h2><button type="button" data-close>✕</button></div><p>不上传工程文件。填写本机完整文件或文件夹路径，可定位到工程所在目录。</p><label>工程名称<input name="name" required></label><label>完整路径<input name="local_path" placeholder="D:\\AOI\\客户项目\\检测工程" required></label><label>工程版本<input name="engineering_version" value="v1"></label><p class="error"></p><button class="primary">保存工程路径</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const j=await request('/api/local-engineering',Object.fromEntries(new FormData(e.target)));S=await request('/api/state');d.close();if(done)done(j.id);else render()}catch(e){d.querySelector('.error').textContent=e.message}}}
const uploadV11=uploadDialog;uploadDialog=function(kind){if(kind==='engineering'){localEngineering();return}uploadV11(kind);const d=Array.from(document.querySelectorAll('dialog')).at(-1),sel=d.querySelector('[name=engineering_id]');const b=document.createElement('button');b.type='button';b.textContent='＋ 登记本地路径并绑定';sel.after(b);b.onclick=()=>localEngineering(id=>{sel.innerHTML='<option value="0">后期再绑定</option>'+S.data.engineering_projects.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.local_path||x.engineering_version||'')}</option>`).join('');sel.value=id})};
const editV11=edit;edit=function(id){if(table==='engineering_projects'){if(!id){localEngineering();return}baseEdit(id);const e=S.data.engineering_projects.find(x=>x.id===id);$('#fields [name=asset_id]').closest('label').hidden=true;const block=document.createElement('div');block.innerHTML=`<p>${esc(e.local_path||'旧版上传工程')}</p>${e.local_path?'<button type="button" data-open>打开所在文件夹</button><button type="button" data-copy>复制路径</button>':`<a href="/api/media?id=${e.asset_id}&mode=original">下载旧工程</a>`}`;$('#fields').append(block);block.querySelector('[data-open]')?.addEventListener('click',async()=>{try{await request('/api/open-engineering',{id});toast('已在本机定位工程')}catch(e){toast(e.message)}});block.querySelector('[data-copy]')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(e.local_path);toast('已复制路径')}catch{toast(e.local_path)}});return}
if(table==='videos'&&!id){videoUpload();return}
if(table==='asset_defects'&&!id){bagDefects();return}
editV11(id);
if(table==='videos')for(const n of ['file_name','relative_path','file_size'])$('#fields [name='+n+']').readOnly=true;
const refNames=table==='products'?['category_id','material_id']:table==='product_categories'?['parent_id']:[];
for(const n of refNames){const sel=$('#fields [name='+n+']'),target=n==='material_id'?'materials':'product_categories';if(table==='product_categories'&&id){const forbidden=new Set([id]);let changed=true;while(changed){changed=false;for(const r of S.data.product_categories)if(forbidden.has(r.parent_id)&&!forbidden.has(r.id)){forbidden.add(r.id);changed=true}}Array.from(sel.options).forEach(o=>{if(forbidden.has(Number(o.value)))o.remove()})}const b=document.createElement('button');b.type='button';b.textContent=n==='material_id'?'＋ 新增材质':'＋ 新增分类';sel.after(b);b.onclick=()=>{const d=extraDialog(`<form><h2>${b.textContent.slice(2)}</h2><label>名称<input name="name" required></label><button type="button" data-close>取消</button><button class="primary">保存并选中</button><p class="error"></p></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const j=await request('/api/save',{table:target,record:{name:e.target.elements.name.value.trim()}});S=await request('/api/state');sel.add(new Option(label(target,j.id),j.id));sel.value=j.id;d.close()}catch(e){d.querySelector('.error').textContent=e.message}}}}};
const rowsV11=drawRows;drawRows=function(){baseDrawRows();if(table==='videos')$('#rows').querySelectorAll('[data-edit]').forEach(b=>{const v=S.data.videos.find(x=>x.id==b.dataset.edit),play=document.createElement('button');play.textContent='▶ 播放';play.onclick=()=>playVideo(v);b.after(play)})};
function playVideo(v){extraDialog(`<div class="dialogtop"><h2>${esc(v.name)}</h2><button data-close>✕</button></div><video controls preload="metadata" style="width:100%;max-height:65vh" src="/api/video?id=${v.id}"></video><p>绑定图片：${esc(label('images',v.image_id))}</p><a href="/api/video?id=${v.id}" download="${esc(v.file_name)}">下载视频原文件</a><p class="subtle">预览取决于浏览器编码支持，推荐 H.264 MP4；其他格式可下载播放。</p>`)}
function videoUpload(imageId){if(!S.data.images.length){toast('请先上传产品图片，再绑定视频');return}const d=extraDialog(`<form><div class="dialogtop"><h2>上传视频资料</h2><button type="button" data-close>✕</button></div><label>绑定产品图片<select name="image_id" required><option value="">请选择图片</option>${S.data.images.map(i=>`<option value="${i.id}" ${i.id===imageId?'selected':''}>${esc(label('images',i.id))}</option>`).join('')}</select></label><label>视频名称<input name="title" required></label><label>本地视频<input type="file" name="file" accept=".mp4,.webm,.mov,.avi,.mkv,.m4v" required></label><p>单文件上限 1 GB。一个图片可绑定多个视频，文件保存到本机。</p><p class="error"></p><button class="primary">上传并绑定</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,btn=f.querySelector('.primary');btn.disabled=true;try{const file=f.elements.file.files[0];if(file.size>1024**3)throw Error('视频超过 1 GB');d.querySelector('.error').textContent='正在上传…';const q=new URLSearchParams({kind:'video',name:file.name,image_id:f.elements.image_id.value,title:f.elements.title.value});const r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:file}),j=await r.json();if(!r.ok)throw Error(j.error);d.close();await refresh();toast('视频已保存并绑定图片')}catch(e){d.querySelector('.error').textContent=e.message}finally{btn.disabled=false}}}
const galleryV11=drawGallery;drawGallery=function(){galleryV11();$('#imagecards').querySelectorAll('[data-onebind]').forEach(b=>{const id=Number(b.dataset.onebind),add=document.createElement('button');add.textContent='＋ 视频';add.onclick=()=>videoUpload(id);b.after(add);for(const v of S.data.videos.filter(v=>v.image_id===id)){const play=document.createElement('button');play.textContent='▶ '+v.name;play.onclick=()=>playVideo(v);add.after(play)}});document.querySelector('[data-newlocalengineering]')?.remove();const btn=document.createElement('button');btn.dataset.newlocalengineering='1';btn.textContent='＋ 登记工程路径';btn.onclick=()=>localEngineering(()=>render());$('#bindengineering').after(btn);};
const bindV11=bindDialog;bindDialog=function(id){bindV11(id);const d=Array.from(document.querySelectorAll('dialog')).at(-1),sel=d.querySelector('select'),b=document.createElement('button');b.textContent='＋ 登记本地工程路径';sel.after(b);b.onclick=()=>localEngineering(eid=>{sel.add(new Option(label('engineering_projects',eid),eid));sel.value=eid})};
function bagDefects(){const d=extraDialog(`<form><div class="dialogtop"><h2>资料包绑定多个缺陷</h2><button type="button" data-close>✕</button></div><label>资料包<select name="asset_id" required><option value="">请选择</option>${S.data.assets.filter(a=>a.asset_type==='archive').map(a=>`<option value="${a.id}">${esc(a.file_name)}</option>`).join('')}</select></label><p>勾选多个缺陷；每种缺陷保存一条关系，已有关系不会重复。</p>${S.data.defect_types.map(x=>`<label style="display:block"><input type="checkbox" name="defect_ids" value="${x.id}"> ${esc(x.name)}</label>`).join('')||'<p>请先在缺陷字典新增缺陷。</p>'}<label>说明<input name="remark"></label><p class="error"></p><button class="primary">保存全部关系</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await request('/api/bag-defects',{asset_id:f.get('asset_id'),defect_ids:f.getAll('defect_ids'),remark:f.get('remark')});d.close();await refresh();toast('多缺陷关系已保存')}catch(e){d.querySelector('.error').textContent=e.message}}}

guide=function(){$('#content').innerHTML=title('AOI DATAS / V1.2','岳一科技数据资产中枢','本地图片、工程路径与视频资料统一管理。')+`<section class="panel">${[['产品与字典','产品无需填写编号。可先在产品分类、材质字典中建立多个选项，也可在产品新增窗口中直接新增并选中；后续产品复用下拉选项。'],['上级分类','先创建大类，再创建子类并选择上级。可在窗口中快速新增大类；系统会阻止分类循环。'],['工程路径','在检测工程页登记本地绝对路径。上传图片时可新增路径并绑定，也可在图片库中批量绑定。点击工程名称后可打开所在文件夹或复制路径。Windows 本机服务支持定位；Docker 或其他电脑访问请复制路径。'],['视频资料','在视频资料表或图片卡片的“＋ 视频”上传，选择绑定图片。一张图片可有多个视频。支持播放、拖动与下载；预览推荐 H.264 MP4。'],['资料包与缺陷','新增资料包—缺陷关系时勾选多个缺陷，系统一次保存多条关系，不会重复写入，也不会把包级缺陷自动赋给每张图片。'],['升级与备份','先停止旧程序并备份整个 data 文件夹，再将 data 复制到新版目录后启动。首次启动自动新增字段与视频表；既有图片、工程和关系继续保留。JSON 不包含原文件。']].map(([a,b],i)=>`<div class="step"><b>${i+1}</b><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</section>`};

// Account state is supplied by the server; write authorization is enforced by every API.
pages.accounts=['♙','账号管理'];
function accountDialog(){const d=extraDialog(`<form><h2>账号登录</h2><label>账号<input name="username" autocomplete="username" required></label><label>密码<input name="password" type="password" autocomplete="current-password" required></label><p class="error"></p><button type="button" data-close>取消</button><button class="primary">登录</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await request('/api/auth/login',Object.fromEntries(new FormData(e.target)));d.close();await refresh()}catch(e){d.querySelector('.error').textContent=e.message}}}
function accountControls(){
let bar=$('#account-controls');if(!bar){bar=document.createElement('span');bar.id='account-controls';document.querySelector('header > div:last-child').append(bar)}
bar.innerHTML=S.auth?` <span>${esc(S.auth.username)} · ${S.auth.role==='admin'?'管理员':'录入员'}</span> <button id="logout">退出</button>`:' <span>访客 · 只读</span> <button id="login">登录录入</button>';
$('#login')?.addEventListener('click',accountDialog);$('#logout')?.addEventListener('click',async()=>{await request('/api/auth/logout',{});await refresh()});
$('#engine').textContent=S.engine+' · '+S.schema.length+' 张表';
applyPermissions();
}
function applyPermissions(){if(!S)return;const admin=S.auth?.role==='admin';for(const b of document.querySelectorAll('#content button, #rows button')){
const text=b.textContent.trim();const adminOnly=/加载示例|导入/.test(text);const deletion=b.hasAttribute('data-delete')||/删除|解除绑定|取消绑定/.test(text);
const mutation=deletion||/新增|编辑|录入|上传|导入|绑定|加载示例|登记|保存/.test(text);
if((mutation&&!S.auth)||((deletion||adminOnly)&&!admin)){b.disabled=true;b.title=deletion?'仅管理员可删除或解除关联':'请登录后录入';}
}if(page==='imports'&&!S.auth){for(const field of document.querySelectorAll('#content input,#content textarea,#content select,#content button'))field.disabled=true}}
const renderWithAccounts=render;render=function(){if(page==='accounts'){ $('#crumb').textContent='账号管理';accounts();accountControls();return}renderWithAccounts();accountControls()};
new MutationObserver(()=>{if(S)applyPermissions()}).observe(document.querySelector('#content'),{childList:true,subtree:true});
async function accounts(){if(S.auth?.role!=='admin'){$('#content').innerHTML=title('ACCOUNTS','账号管理','仅管理员可以管理账号。');return}
$('#content').innerHTML=title('ACCOUNTS','账号管理','录入员可新增和编辑；只有管理员可删除。导入与示例数据操作也仅限管理员。')+`<section class="panel"><h2>创建账号</h2><form id="new-account"><label>账号<input name="username" required maxlength="100"></label><label>密码<input name="password" type="password" required minlength="12" autocomplete="new-password"></label><label>角色<select name="role"><option value="editor">录入员</option><option value="admin">管理员</option></select></label><button class="primary">创建账号</button></form><div id="user-list"></div></section>`;
$('#new-account').onsubmit=async e=>{e.preventDefault();try{await request('/api/auth/users',Object.fromEntries(new FormData(e.target)));await accounts();toast('账号已创建')}catch(e){toast(e.message)}};
try{const users=await request('/api/auth/users');$('#user-list').innerHTML=users.map(u=>`<p>${esc(u.username)} · ${u.role==='admin'?'管理员':'录入员'} <button data-reset-user="${u.id}">重置密码</button></p>`).join('');$('#user-list').querySelectorAll('[data-reset-user]').forEach(b=>b.onclick=()=>{const d=extraDialog(`<form><h2>重置密码</h2><label>新密码<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><p class="error"></p><button type="button" data-close>取消</button><button>保存密码</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await request('/api/auth/reset-password',{id:Number(b.dataset.resetUser),password:e.target.elements.password.value});d.close();toast('密码已重置，该账号的已有会话已注销')}catch(e){d.querySelector('.error').textContent=e.message}}})}catch(e){toast(e.message)}}

const uploadWithNames=uploadDialog;uploadDialog=function(kind){uploadWithNames(kind);if(kind!=='image')return;const d=Array.from(document.querySelectorAll('dialog')).at(-1),input=d.querySelector('[name=localfiles]'),names=document.createElement('div');input.after(names);input.addEventListener('change',()=>{names.innerHTML=Array.from(input.files).map((f,i)=>`<label>保存文件名（保留扩展名）<input data-upload-name="${i}" value="${esc(f.name)}" required maxlength="191"></label>`).join('')})};
function renameImage(id){const image=S.data.images.find(i=>i.id===id),asset=S.data.assets.find(a=>a.id===image.asset_id);const d=extraDialog(`<form><h2>重命名图片</h2><label>新文件名<input name="name" value="${esc(asset.file_name)}" required maxlength="191"></label><p>同时更新本地原文件名称与记录，保留关联、图片内容和扩展名。</p><p class="error"></p><button type="button" data-close>取消</button><button>保存新名称</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await request('/api/rename-image',{image_id:id,name:e.target.elements.name.value});d.close();await refresh();toast('图片及本地文件已重命名')}catch(e){d.querySelector('.error').textContent=e.message}}}
const galleryWithRename=drawGallery;drawGallery=function(){galleryWithRename();if(!S.auth)return;$('#imagecards').querySelectorAll('[data-onebind]').forEach(b=>{const button=document.createElement('button');button.textContent='重命名';button.onclick=()=>renameImage(Number(b.dataset.onebind));b.after(button)})};
const editWithAttachments=edit;edit=function(id){editWithAttachments(id);if(!id)return;if(table==='images'&&S.auth){const b=document.createElement('button');b.type='button';b.textContent='重命名图片文件';b.onclick=()=>{ $('#dialog').close();renameImage(id)};$('#fields').append(b)}if(table==='technical_agreements'){const block=document.createElement('div');block.innerHTML=agreementFileLinks(id)+(S.auth?'<button type="button" data-attach-agreement>上传协议附件</button>':'');block.querySelector('button')?.addEventListener('click',()=>agreementUpload(id));$('#fields').append(block)}};
function agreementFileLinks(id){return '<h3>技术协议附件</h3>'+((S.data.agreement_files||[]).filter(f=>f.agreement_id===id).map(f=>`<p><a href="/api/media?id=${f.asset_id}&mode=original">↓ ${esc(S.data.assets.find(a=>a.id===f.asset_id)?.file_name||'附件')}</a></p>`).join('')||'<p>暂无附件</p>')}
function agreementUpload(id){const d=extraDialog(`<form><h2>上传技术协议附件</h2><p>保存至运行服务电脑的工程数据目录，不会覆盖同名文件。</p><label>文件<input name="file" type="file" required></label><label>保存文件名<input name="name" required maxlength="191"></label><p class="error"></p><button type="button" data-close>取消</button><button type="submit">上传附件</button></form>`);const f=d.querySelector('form');f.elements.file.onchange=()=>{f.elements.name.value=f.elements.file.files[0]?.name||''};f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;try{const file=f.elements.file.files[0];if(file.size>256*1024*1024)throw Error('单个附件不能超过 256 MB');const q=new URLSearchParams({kind:'agreement',agreement_id:id,name:f.elements.name.value});const response=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:file}),j=await response.json();if(!response.ok)throw Error(j.error);d.close();$('#dialog').close();await refresh();toast('协议附件已保存')}catch(e){d.querySelector('.error').textContent=e.message}finally{button.disabled=false}}}
const rowsWithAttachments=drawRows;drawRows=function(){rowsWithAttachments();if(table==='technical_agreements'){$('#rows').querySelectorAll('[data-edit]').forEach(b=>{const id=Number(b.dataset.edit),block=document.createElement('span');block.innerHTML=agreementFileLinks(id);b.parentNode.append(block);if(S.auth){const button=document.createElement('button');button.textContent='上传协议附件';button.onclick=()=>agreementUpload(id);b.after(button)}})}};
